create or replace function public.validate_reclass_teacher_attendance_state() returns trigger language plpgsql security definer set search_path to 'public' as $$ declare v_teacher uuid; begin select teacher_id into v_teacher from public.session_occurrences where id=new.occurrence_id and status <> 'cancelled'; if v_teacher is null then raise exception 'Attendance occurrence is invalid or cancelled'; end if; if new.teacher_id <> v_teacher then raise exception 'Attendance teacher does not match session occurrence teacher'; end if; if tg_op='UPDATE' and old.approval_status <> 'pending' and (new.approval_status <> old.approval_status or new.status <> old.status) then raise exception 'Reviewed attendance is immutable'; end if; if new.approval_status='approved' and (new.reviewed_by is null or new.reviewed_at is null) then raise exception 'Approved attendance requires reviewer and review time'; end if; if new.approval_status='rejected' and (new.reviewed_by is null or new.reviewed_at is null) then raise exception 'Rejected attendance requires reviewer and review time'; end if; if new.approval_status='pending' and (new.reviewed_by is not null or new.reviewed_at is not null) then raise exception 'Pending attendance cannot have reviewer metadata'; end if; return new; end; $$;
drop trigger if exists trg_validate_reclass_teacher_attendance_state on public.teacher_attendance;
create trigger trg_validate_reclass_teacher_attendance_state before insert or update on public.teacher_attendance for each row execute function public.validate_reclass_teacher_attendance_state();
revoke execute on function public.validate_reclass_teacher_attendance_state() from public,anon,authenticated;
